INSERT INTO `notify` VALUES (1,'Hỗ trợ nhiệm vụ','1) Hỗ trợ nhiệm vụ TĐST:\nNgày thứ 2-3-4 trong tuần từ 5h\nđến 7h và từ 17h đến hết 19h,\nchỉ những cư dân đang làm nhiệm\nvụ này mới vào được map có boss,\nnày xuất hiện.\n(Núi khỉ đen, hang khỉ đen, núi khỉ\nđỏ).\n\n2) Hỗ trợ nhiệm vụ Xên Bọ Hung:\nNgày thứ 2-3-4 trong tuần, từ 2 giờ\nsáng đén hết 4 giờ sáng và từ 2 giờ\nchiều đến hết 4 giờ chiều, chỉ\nnhững cư dân đang làm nhiệm vụ\nnày mới vào được map có boss này\nxuất hiện.\n(Thị trấn Ginder, Võ đài Xên bọ\nhung).'),(201,'Tài khoản & bảo mật','Mục \"Tài khoản\": xem thông tin tài khoản đang\nđăng nhập.\n\n- \"Đổi tài khoản\": đăng xuất, quay lại màn\nhình chọn máy chủ.\n- Đổi mật khẩu / mã bảo vệ: làm trên website\nhoặc NPC tương ứng.\n\nBẢO MẬT:\n- Không đưa mật khẩu, mã OTP cho BẤT KỲ ai,\nkể cả người xưng là admin.\n- Nghi ngờ bị lộ -> đổi mật khẩu NGAY.\n- Không dùng chung tài khoản với người lạ.'),(202,'Chat thế giới','Chat thế giới: kênh nhắn tin toàn máy chủ,\nmọi người đều thấy.\n\nMở: Chức năng -> Chat thế giới -> gõ nội\ndung -> gửi.\n\nDùng để: tìm team, hỏi đáp, mua bán, báo\nboss.\n\nLưu ý: không spam, không quảng cáo để tránh\nbị xử lý.'),(203,'Đổi khu vực','Đổi khu vực: chuyển sang khu (zone) khác\ntrong CÙNG bản đồ.\n\nCách dùng: Chức năng -> Đổi khu vực -> chọn\nkhu trống.\n\nDùng khi:\n- Khu đang đông người, tranh quái.\n- Muốn train riêng với bạn bè cùng bản đồ.\n\nMỗi khu có số người tối đa - chọn khu còn\ntrống.'),(204,'Đổi cờ','Đổi cờ: chọn cờ hiệu hiển thị cho nhân vật.\n\nCách dùng: Chức năng -> Đổi cờ -> chọn cờ\n-> Xác nhận.\n\n- Miễn phí, đổi lại sau 60 giây.\n- Không đổi được ở một số bản đồ sự kiện\n(map Mabư, đấu trường).\n\nDanh sách cờ do server cấp - xem hết danh\nsách để chọn cờ ưng ý.'),(205,'Sự kiện','Server mở các sự kiện định kỳ: Trung Thu,\nsự kiện quái, sự kiện boss...\n\nTheo dõi:\n- Thông báo server khi sự kiện bật/tắt.\n- Mục Thông báo này (admin cập nhật).\n\nSự kiện thường có: tỉ lệ rơi tăng, boss\nriêng, mốc thưởng, vật phẩm giới hạn.\n\nĐừng quên nhận quà sự kiện trước khi sự\nkiện đóng.'),(206,'Điểm Farm','Điểm Farm tích lũy khi chơi:\n\nNhận khi:\n- Đánh quái ở mọi bản đồ (500 - 1500/lần,\nVIP được thêm).\n- Đánh boss (1 - 20.000).\n- Dùng Capsule (có khi vài triệu điểm).\n\nDùng để:\n- Nâng cấp Bông Tai, Chân Mệnh.\n- Mở giới hạn sức mạnh và các chức năng\nghép (Combine).\n\nXem số điểm trong thông tin nhân vật.'),(207,'Giftcode','Giftcode: mã quà miễn phí phát trên website,\nfanpage, sự kiện.\n\nNhập trong game:\n1. Đến NPC ÔNG GOHAN hoặc NPC SANTA.\n2. Chọn mục Giftcode.\n3. Nhập chính xác mã -> nhận quà vào túi.\n\nLưu ý:\n- Chỉ nhập code ở 2 NPC trên hoặc trang web\nchính thức.\n- KHÔNG đưa mật khẩu / mã OTP cho ai.\n- Mỗi code có số lượng lượt - dùng sớm.'),(208,'Ký gửi bán đồ','Ký gửi: bán vật phẩm cho người chơi khác,\nbán được cả khi bạn offline.\n\nCách bán:\n1. Mở chức năng Ký gửi.\n2. Chọn vật phẩm, đặt GIÁ bằng Ngọc.\n3. Đồ treo lên chờ người mua.\n\nCách mua: vào Ký gửi, chọn đồ, trả giá.\n\nLưu ý: xem kỹ giá trước khi mua - đồ đã bán\nkhông lấy lại được. Giá thấp thì mau hết,\ngiá cao thì lâu có người mua.'),(209,'Mini game quay số','Mini game = QUAY SỐ MAY MẮN tại NPC Lý\nTiểu Nương.\n\n- Mua lượt quay, chọn con số may mắn.\n- Quay trúng là nhận thưởng ngay vào túi.\n\nĐây là trò may mắn - quay cho vui, đừng all\nin tiền nhé!'),(210,'Tầm Bảo (vòng quay)','Vòng quay Tầm Bảo (icon Chức năng -> Tầm\nBảo):\n\n- Dùng CHÌA KHÓA (vật phẩm) để quay.\n- Chọn ô quay, mỗi lần quay tốn 1 chìa khóa.\n- Trúng vật phẩm theo tỉ lệ từng ô.\n\nQuyền lợi:\n- Tích lũy ĐIỂM QUAY -> mở mốc thưởng.\n- Số lượt quay cộng vào TOP Tầm Bảo.\n\nChìa khóa là vật phẩm đặc biệt - xem cách\nnhận ngay trong giao diện Tầm Bảo.'),(211,'Phúc Lợi & Quà','Mở icon Chức năng -> Phúc Lợi (khi đang\nđược bật).\n\nCác tab:\n- Quà Online: chơi đủ thời gian nhận quà.\n- Điểm danh: nhận quà mỗi ngày.\n- Nạp: các mốc nạp nhận thưởng.\n- Coin / Shop: đổi và mua bằng Coin, item\nhạn trang.\n\nCách dùng: chọn tab -> chọn mốc -> nhận\nquà.\n\nMục \"Hỗ trợ nhiệm vụ\" cuối danh sách giải\nthích khung giờ boss theo nhiệm vụ.'),(212,'Săn Boss','Boss xuất hiện theo lịch trên nhiều bản đồ.\n\n- Server thông báo \"BOSS ... vừa xuất hiện\ntại ...\" khi boss ra map.\n- Vào đúng bản đồ + khu vực, đánh cùng mọi\nngười.\n- Boss rơi đồ hiếm, Điểm Farm và phần thưởng\ntop dame.\n\nBoss Thế Giới có bảng xếp hạng sát thương\nriêng.\n\nBoss mạnh nên đi theo nhóm bang hoặc team,\nmang đủ đồ hồi phục trước khi vào đánh.'),(213,'Nâng cấp - Ghép đồ','NPC Bơ Hạt Mít là trung tâm nâng cấp:\n\n- Đục khảm lỗ, Ép sao phụ kiện, Gỡ sao pha\nlê.\n- Nâng cấp Bông Tai + Mở chỉ số Bông Tai\n(map Up Bông Tai kiếm nguyên liệu).\n- Nâng cấp Chân Mệnh, Mở chỉ số Cải trang.\n- Nâng cấp Cánh, Ghép Ngọc Rồng, Ghép Rương\nThần Bí.\n- Ép sao trang bị / Pha lê hoá trang bị.\n- Võ đài Sinh Tử cũng ở NPC này.\n\nMỗi chức năng đều có mô tả điều kiện ngay\ntrong menu - đọc kỹ trước khi làm.'),(214,'Set đồ 5 món','Set đồ: bộ 5 món cùng kiểu, đeo đủ 5 món\nmới kích hoạt bonus.\n\nCách nhận biết:\n- Mỗi set ứng với một OPTION riêng trên đồ.\n- Chỉ tính 5 món đầu: áo, quần, găng, giày,\nnhẫn.\n- Trùng option trong 1 món chỉ đếm 1 lần.\n- Đeo đủ 5/5 món thì option set mới cộng\nbonus đầy đủ.\n\nXem set: so option trên đồ với nhau.\nTheo dõi shop, sự kiện và boss để kiếm đủ\nbộ.'),(215,'Cung Mệnh','Cung Mệnh: NPC Bội Mông (Rừng Karin).\n\n- Tối đa 120 cấp, cứ 10 cấp bắt buộc ĐỘT\nPHÁ trước khi lên tiếp.\n- Nâng cấp thường: Mảnh Tinh Tú.\n- Đột phá: Mảnh Tinh Tú + Ngọc Tinh Đồ.\n\nQuyền lợi mỗi cấp: +2000 HP, +2000 KI, +200\nSD cộng thẳng, cộng thêm % theo cấp và các\nbậc option riêng.\n\nKhông đủ vật tư, menu hiện đúng số còn\nthiếu. Thu thập vật tư qua hoạt động trong\ngame.'),(216,'Cây phép (Đậu Thần)','Cây Đậu Thần ở nhà bạn - tự động kết hạt\nđậu theo thời gian.\n\nVòng chơi:\n1. Cây tự tích đậu, kể cả khi bạn offline.\n2. Thu hoạch lấy hạt vào túi.\n3. Nâng cấp cây bằng VÀNG - cấp cao nhiều ô\nhơn nhưng kết chậm hơn.\n4. Kết hạt nhanh: 4 ngọc. Nâng cấp nhanh:\n9 ngọc.\n\nCấp tối đa 10. Hủy nâng cấp được hoàn nửa\nvàng. Quá trình nâng tiếp tục kể cả khi tắt\ngame.'),(217,'Địa Đạo','Địa Đạo nhận song song với Thiên Đạo.\n\nNguồn nhận:\n- Nạp tiền: cứ 5.000đ = +1 Địa Đạo.\n- NPC các mốc +500 / +1200 / +3000.\n- Rương Ghi Danh 1-6.\n\nQuyền lợi: mở hiệu ứng riêng và tăng dần\ntheo cấp Địa Đạo.\n\nNạp 1 lần được CẢ Thiên Đạo, Địa Đạo, VIP\nvà Điểm PassFree - nạp là ăn đủ bộ.\n\nXem chi tiết: menu Hiệu ứng Địa Đạo.'),(218,'Thiên Đạo','Thiên Đạo tăng theo cấp, là chỉ số \"chơi\nlâu càng mạnh\".\n\nNguồn nhận:\n- Nạp tiền: cứ 10.000đ = +1 Thiên Đạo.\n- NPC tặng các mốc +99 / +250 / +600.\n- Rương Ghi Danh.\n\nQuyền lợi:\n- Cơ bản: HP/KI/SD tăng theo cấp Thiên Đạo.\n- Từ cấp 30: mở hiệu ứng riêng theo giới\n(Nam: Kaioken, Nữ: Liên hoàn, Xen: Biến\nKhỉ).\n- Cao cấp: tăng dame boss, rơi ngọc/vàng,\nchoáng lâu hơn, buff đệ tử.\n\nXem hiệu ứng: menu Hiệu ứng Thiên Đạo.'),(219,'Tu tiên','Tu Tiên gồm: Linh Khí, Cảnh Giới, Thiên Phú.\n\nNhận linh khí:\n- Tự động nhận theo thời gian (kể cả khi\nđang chơi).\n- Nhặt đồ rơi từ quái (cần TẨY THIÊN PHÚ\ntrước - thiên phú 0 thì không tu luyện\nđược).\n\nLên cảnh giới: NPC Tu Tiên -> Độ Kiếp\n(tốn 50M linh khí, có tỉ lệ thất bại; mang\nthần khí trong túi để cộng tỉ lệ).\n\nTẩy Luyện Thiên Phú: đổi chỉ số thiên phú\n(cần cảnh 10, tỉ lệ thành công thấp).\n\nThọ Nguyên: đếm ngược. Hết thọ nguyên = mất\nsạch linh khí, cảnh giới, thiên phú. Độ kiếp\ntành công để cộng thọ nguyên.\n\nGõ lệnh chat \"tutien\" để mở menu nhanh.'),(220,'Chuyển sinh','Chuyển sinh = đổi sức mạnh hiện tại lấy\nchỉ số GỐC vĩnh viễn.\n\nĐiều kiện (nhân vật):\n- Tu Tiên đạt cảnh Trúc Cơ đỉnh phong.\n- Lượng Bạc >= 50.000.\n- Sức mạnh >= 150 nghìn tỷ + vàng.\n\nThành công: reset SM và tiềm năng về 0,\nđược +500k HP/KI gốc, +50k dame gốc, +1000\ngiáp gốc, và +30% HP/KI/SD/Giáp mỗi cấp\nchuyển sinh.\n\nTHẤT BẠI: vẫn mất sạch SM và tiềm năng mà\nkhông được gì - cân nhắc kỹ trước khi làm!\n\nChuyển sinh đệ tử: mục riêng trong cùng NPC.'),(221,'Sinh Em Bé','Sau khi kết hôn, hai vợ chồng có thể sinh\nEm Bé (con chung):\n\n1. NPC Kết Hôn -> mục Sinh Em Bé.\n2. Đặt tên cho bé.\n3. Bé có linh căn ngẫu nhiên và sức mạnh ban\nđầu ngẫu nhiên.\n\nBé lớn lên theo cấp và exp, cần cho ăn đều\nđặn (cùng cơ chế với Đạo Lữ - xem mục\n\"Đạo Lữ (Em Bé)\").\n\nBé buff chỉ số cho bố mẹ khi không ở trạng\nthái Về nhà. Bé chết đói thì mất, hãy canh\nthức ăn!'),(222,'Kết hôn','NPC Kết Hôn (bản đồ kết hôn):\n\n1. Làm các cửa ải thu thập vật liệu kết\nhôn.\n2. Đủ vật liệu -> cầu hôn đối phương (đối\nphương phải đang trong game).\n3. Đối phương đồng ý là kết hôn.\n4. Kết hôn cho chỉ số và quyền lợi riêng.\n\nĐiều kiện: cần đạt Tu Tiên cảnh 90 và đủ\nvật liệu hồng ngọc theo yêu cầu.\n\nSau khi kết hôn mới có thể SINH EM BÉ\n(xem mục riêng \"Sinh Em Bé\").'),(223,'Đạo Lữ (Em Bé)','Một hệ thống, hai tên gọi: Đạo Lữ / Em Bé\nRồng. Đây là CON của bạn, khác Đệ tử.\n\nTạo pet:\n- NPC Đạo Lữ hoặc NPC Kết Hôn, hoặc gõ\nlệnh chat \"daolu\".\n- Đặt tên, linh căn ngẫu nhiên.\n\nChăm sóc (quan trọng):\n- Thức ăn giữ trong khoảng 1-500.\n- Mỗi 15 phút server trừ 1 điểm ăn; ăn về 0\n= pet bỏ đi mất vĩnh viễn.\n- Cho ăn no trên 500 pet cũng chết.\n\nTrạng thái: Đi theo / PK người / PK quái /\nVề nhà. Pet chỉ buff chỉ số cho chủ khi\nKHÔNG ở trạng thái Về nhà.'),(224,'Đệ tử','Đệ tử là người bạn đồng hành đánh cùng bạn.\n(Hệ thống riêng, KHÁC Đạo Lữ / Em Bé).\n\n- Đệ tử có chỉ số, skill và trang bị riêng.\n- Mang đồ cho đệ tử được.\n- Xem thông tin: NPC kiểm tra / menu Đệ tử.\n- Chuyển sinh đệ tử để đệ mạnh hơn (xem mục\nriêng \"Chuyển sinh\").\n\nHỢP THỂ VĨNH VIỄN: đổi toàn bộ sức mạnh\nđệ thành TIỀM NĂNG cho nhân vật - MẤT đệ\ntử và trang bị của nó, không lấy lại được!\n\nĐừng nhầm Đệ tử với Đạo Lữ.'),(225,'Bang hội','Bang hội: nơi tập hợp người chơi cùng nhóm.\n\nCách tham gia:\n- Tạo bang: NPC Bang hội -> nhập tên viết\ntắt bang 2-4 ký tự.\n- Vào bang: gửi yêu cầu, bang trưởng duyệt.\n\nTrong menu Bang hội bạn có thể:\n- Xem danh sách thành viên, cấp độ bang.\n- Chat riêng trong bang.\n- Xem thứ hạng bang với bang khác.\n\nTham gia bang để có đội đi boss, đi sự kiện\nvà nhận hỗ trợ từ cao thủ.'),(226,'Sổ sưu tầm (Radar)','Menu Chức năng -> \"Sổ sưu tầm\" (thẻ Radar).\n\n- Sổ sưu tầm sưu tập các thẻ chỉ số.\n- Mỗi thẻ cho một chỉ số riêng khi mở.\n- Gộp đủ bộ để nhận thêm chỉ số cho nhân\nvật.\n\nXem danh sách trong Sổ để biết còn thiếu\nthẻ nào.\n\nSưu tầm từ sớm vì đây là chỉ số cộng dồn\nlâu dài, càng có nhiều thẻ càng mạnh.'),(227,'Kỹ năng','Tab \"Kỹ năng\" liệt kê toàn bộ skill của phái.\n\n- Skill mở theo cấp độ: đạt cấp là học được\ntại NPC dạy kỹ năng.\n- Nâng skill bằng điểm kỹ năng nhận mỗi lần\nlên cấp.\n- Chọn skill để xem mô tả: sát thương, mana\ntiêu thụ, hiệu ứng.\n\nMẹo: ưu tiên nâng skill bạn hay dùng nhất\ntrước khi đi boss hoặc đi sự kiện.'),(228,'Tiềm năng (cộng điểm)','Menu nhân vật -> \"Tiềm năng\": cộng điểm\nmỗi lần lên cấp.\n\nBa chỉ số chính:\n- SD (sát thương): tăng đòn đánh.\n- HP: tăng máu.\n- KI: tăng năng lượng dùng skill.\n\nGợi ý theo phái:\n- Saiyan / Trái Đất: ưu tiên SD và HP.\n- Namek: ưu tiên HP và KI.\n\nMỗi lần lên cấp đều có điểm cộng mới.\nCộng gì tùy lối chơi: đánh nhanh thì SD,\nsống lâu thì HP, xài skill nhiều thì KI.'),(229,'Hành trang & mang đồ','Tab \"Hành trang\" xem toàn bộ vật phẩm đang\nmang theo.\n\nCách mang đồ:\n1. Mở Hành trang -> chọn vật phẩm.\n2. Bấm \"Mặc\" để mang lên người.\n\nCác ô trang bị: áo, quần, găng, giày, nhẫn,\ncải trang, giáp tập luyện, thú cưng, hào\nquang, thú cưỡi.\n\nĐồ có yêu cầu cấp độ và giới tính - không\nđủ điều kiện sẽ không mặc được.\n\nTúi đầy thì để đồ thừa vào Rương (hộp đồ)\nngay trong Hành trang.\n\nChọn đồ để xem chỉ số và option của nó.'),(230,'Nhiệm vụ & lên cấp','Xem nhiệm vụ hiện tại: tab \"Nhiệm vụ\" bên\ntrái màn hình.\n\nCách làm:\n1. Tìm NPC có dấu chấm than vàng.\n2. Nói chuyện, đọc yêu cầu (đánh quái, thu\nthập vật phẩm, lên cấp...).\n3. Hoàn thành, quay lại NPC nộp nhiệm vụ.\n\nMỗi lần nộp được EXP, tiền và vật phẩm.\n\nKhi hết nhiệm vụ hệ thống: đi farm quái ở\nbản đồ hợp với cấp độ của bạn.\n\nMẹo: đứng farm cùng một khu vực sẽ nhanh\nhơn là đổi bản đồ liên tục.'),(231,'Tân thủ:7 bước đầu tiên','DÀNH CHO NGƯỜI MỚI CHƠI\n\nBước 1: Chọn hành tinh (Trái Đất / Namek /\nXen) rồi tạo nhân vật.\n\nBước 2: Nói chuyện NPC đầu bản đồ để nhận\nnhiệm vụ cấp 1, làm liên tục.\n\nBước 3: Đánh quái quanh bản đồ lên cấp,\nnhặt đồ rơi.\n\nBước 4: Mở Hành trang, mang trang bị vào ô\náo / quần / găng / giày / nhẫn.\n\nBước 5: Cộng Tiềm năng mỗi lần lên cấp\n(menu nhân vật -> Tiềm năng).\n\nBước 6: Học kỹ năng khi đủ cấp tại NPC.\n\nBước 7: Nhập Giftcode ở NPC Ông Gohan\nhoặc Santa để nhận quà miễn phí.\n\nLàm nhiệm vụ liên tục là cách lên cấp\nnhanh nhất ở giai đoạn đầu.'),(232,'Cẩm nang: cách dùng','CẨM NANG CHƠI GAME - máy chủ HondaODragon\n\nMục Thông báo này là nơi server gửi hướng\ndẫn chơi game cho bạn.\n\nMỗi chức năng, mỗi nhiệm vụ đều có MỘT MỤC\nRIÊNG bên dưới - chọn từng mục để đọc.\n\nCách đọc:\n- Mục có chấm đỏ nhấp nháy = chưa đọc.\n- Kéo thanh bên dưới để xem hết danh sách.\n- Chọn một mục để mở nội dung.\n\nNếu admin cập nhật nội dung, bạn vào lại\ngame là thấy bản mới nhất.');
